"""PGW GPU validation kernel for Kaggle (generated by benchmarks/kaggle/build.py; do not edit the copy).

Unpacks the embedded pgw source tarball, installs it with its extras, then runs the JOB steps:
``doctor``, ``pytest`` (GPU tests + full suite with the e2e service on CUDA), ``ring`` benches,
and ``validate`` (benchmarks/gpu_validate.py for one model). Everything lands in /kaggle/working.
"""
import base64
import io
import json
import os
import subprocess
import sys
import tarfile
import time
import traceback

T0 = time.time()
OUT = "/kaggle/working"
JOB = json.loads(r'''__JOB__''')
TGZ = """
__PGW_TGZ_B64__
"""
SUMMARY = {"job": JOB, "steps": {}}


def log(*a):
    print(f"[{(time.time() - T0) / 60:6.1f}m]", *a, flush=True)


def save():
    with open(f"{OUT}/summary.json", "w") as f:
        json.dump(SUMMARY, f, indent=1, default=str)


def sh(name, cmd, timeout=3600, env=None, cwd=None):
    log("RUN", name, ":", cmd if isinstance(cmd, str) else " ".join(cmd))
    t = time.time()
    try:
        r = subprocess.run(cmd, shell=isinstance(cmd, str), capture_output=True, text=True, timeout=timeout,
                           env={**os.environ, **(env or {})}, cwd=cwd)
        out, rc = r.stdout + "\n---stderr---\n" + r.stderr, r.returncode
    except subprocess.TimeoutExpired as e:
        out, rc = f"TIMEOUT after {timeout}s\n{e.stdout or ''}\n{e.stderr or ''}", -999
    with open(f"{OUT}/{name}.txt", "w") as f:
        f.write(out if isinstance(out, str) else str(out))
    SUMMARY["steps"][name] = {"rc": rc, "seconds": round(time.time() - t, 1), "tail": out[-1500:]}
    save()
    log("DONE", name, "rc", rc, f"{time.time() - t:.0f}s")
    print(out[-3000:], flush=True)
    return rc, out


# ---- environment -------------------------------------------------------------------------------------
import torch  # noqa: E402

SUMMARY["env"] = {"python": sys.version, "torch": torch.__version__, "cuda": torch.version.cuda,
                  "gpu": torch.cuda.get_device_name(0) if torch.cuda.is_available() else None,
                  "gpu_count": torch.cuda.device_count(), "cpu_count": os.cpu_count()}
try:
    SUMMARY["env"]["mem"] = open("/proc/meminfo").read().split("\n")[:2]
    SUMMARY["env"]["disk"] = subprocess.run("df -h / /tmp /kaggle/working", shell=True, capture_output=True,
                                            text=True).stdout
except Exception:  # noqa: BLE001
    pass
log(SUMMARY["env"])
save()

SRC = "/tmp/pgwsrc"
os.makedirs(SRC, exist_ok=True)
if TGZ.strip():
    tarfile.open(fileobj=io.BytesIO(base64.b64decode(TGZ)), mode="r:*").extractall(SRC, filter="data")
else:  # a bundle over Kaggle's script size limit ships as a private dataset (build.py: "source": "dataset")
    import glob

    found = sorted(glob.glob("/kaggle/input/**/pgw.tar.xz", recursive=True))
    log("source tarball from the dataset", found)
    tarfile.open(found[0], mode="r:*").extractall(SRC, filter="data")
ROOT = f"{SRC}/pgw"
rc, _ = sh("pip_install", [sys.executable, "-m", "pip", "install", "-q", "-e", f"{ROOT}[dev]"], timeout=1800)
if rc != 0:
    sh("pip_install_retry", [sys.executable, "-m", "pip", "install", "-e", f"{ROOT}[dev]"], timeout=1800)
sh("pip_freeze", [sys.executable, "-m", "pip", "freeze"], timeout=300)

for step in JOB["steps"]:
    try:
        kind = step["kind"]
        if kind == "doctor":
            sh("doctor", [sys.executable, "-m", "pgw.cli", "doctor", "--json"], timeout=900, cwd=ROOT)
        elif kind == "pytest":
            sh(step["name"], [sys.executable, "-m", "pytest", *step["args"], "-p", "no:cacheprovider"],
               timeout=step.get("timeout", 3600), env=step.get("env", {}), cwd=ROOT)
        elif kind == "ring":
            outs = {}
            for s in step["shapes"]:
                for ring in step.get("rings", ["K40A12"]):
                    name = f"ring_{s}_{ring}".replace(".", "_")
                    rc, out = sh(name, [sys.executable, "-m", "pgw.cli", "bench", "ring", "--json", "--repeat", "5",
                                        "--shape", s, "--ring", ring, "--rows", "1", "--rows", "32", "--rows",
                                        "256", *step.get("extra", [])], timeout=1800, cwd=ROOT)
                    try:
                        txt = out.split("---stderr---")[0]
                        outs[name] = json.loads(txt[txt.index("["):])
                    except Exception:  # noqa: BLE001
                        outs[name] = None
            with open(f"{OUT}/ring_bench.json", "w") as f:
                json.dump(outs, f, indent=1)
        elif kind == "validate":
            sh(f"validate_{step['label']}",
               [sys.executable, f"{ROOT}/benchmarks/gpu_validate.py", "--out", f"{OUT}/validate", *step["args"]],
               timeout=step.get("timeout", 5400), cwd=ROOT)
        elif kind == "shell":
            rc, _ = sh(step["name"], step["cmd"], timeout=step.get("timeout", 1800), cwd=ROOT)
            if rc != 0 and step.get("required"):
                # e.g. the native build: every later number would measure the slow fallback, not the code
                SUMMARY["aborted"] = f"required step {step['name']} failed (rc {rc}); later steps not run"
                save()
                log("ABORT", SUMMARY["aborted"])
                break
    except Exception:  # noqa: BLE001
        SUMMARY["steps"][f"crash_{step.get('kind')}"] = traceback.format_exc()
        save()
SUMMARY["total_minutes"] = round((time.time() - T0) / 60, 1)
save()
log("ALL DONE")
